values ('dialog_fq_star_045', 'fq_star_045', 'npc_legion_class_trainer', 'greeting', '[{"id": "greeting", "text": "Stand ready. Soul Fragmenters", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": ""}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Grand Justiciar Aurelius wrote the code in our home star''s ashes. It has never been wrong. When it says advance, we advance. Today it says: prove your worth.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": ""}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Warpath Standard: A Debt Repaid 03. In Cradle Expanse: Defeat 7 AETHEL_ABYSSAL_REAVER. Complete the task as assigned and report who stood beside you when the line held.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 754)
