values ('dialog_fq_star_063', 'fq_star_063', 'npc_legion_class_trainer', 'greeting', '[{"id": "greeting", "text": "Legionnaire. Jotunn Blockade — Gigantic Jotunns in the Severance Faultline''s deep access corridors are blo...", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": ""}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Legion''s history is written in blood of those before us. Every Legionnaire adds a chapter. Make yours worth reciting.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": ""}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Canyon Claim: Ashes on the Route 04. In Titan Graveyard: Defeat 1 CRYSTAL_TYRANT. Complete the task as assigned and report who stood beside you when the line held.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 772)
